using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using GiantGrey.TileWorldCreator;using Newtonsoft.Json.Linq;
public static class InspectMapAuthoring{public static string Main(){var j=new JArray();foreach(var m in UnityEngine.Object.FindObjectsByType<TileWorldCreatorManager>(FindObjectsInactive.Include,FindObjectsSortMode.None)){var c=m.configuration;j.Add(new JObject{{"manager",m.name},{"configPath",AssetDatabase.GetAssetPath(c)},{"showPaintGrid",c!=null&&c.showPaintGrid},{"debugClusters",m.showClusterCellsDebug},{"width",c?.width},{"height",c?.height}});}File.WriteAllText("Docs/Measurements/2026-10-03-performance/map-authoring.json",j.ToString());return j.ToString();}}
